import{_ as t,o as r,c as a,a6 as o}from"./chunks/framework.Dtv7txdI.js";const u=JSON.parse('{"title":"Stability & Versioning","description":"","frontmatter":{},"headers":[],"relativePath":"v1/stability.md","filePath":"v1/stability.md","lastUpdated":1787648967000}'),i={name:"v1/stability.md"};function n(s,e,d,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="stability-versioning" tabindex="-1">Stability &amp; Versioning <a class="header-anchor" href="#stability-versioning" aria-label="Permalink to “Stability &amp; Versioning”">​</a></h1><p>What Nitr promises about each of its surfaces, from strongest to weakest. One version number covers the whole workspace; the <code>nitr.*</code> Lua API does not get its own — instead the table below states how each surface is allowed to change.</p><div class="warning custom-block github-alert"><p class="custom-block-title">Pre-1.0</p><p></p><p>Nitr is at <code>0.0.0-beta.1</code>. While the version is <code>0.x</code>, <strong>a minor bump may break anything below</strong>. The rules on this page describe the <em>shape</em> of the promise that hardens at 1.0, so you can tell which parts are meant to be depended on and which are meant to move.</p></div><h2 id="the-promise-per-surface" tabindex="-1">The promise per surface <a class="header-anchor" href="#the-promise-per-surface" aria-label="Permalink to “The promise per surface”">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Promise</th></tr></thead><tbody><tr><td><strong>The <code>nitr.*</code> Lua API</strong></td><td>The strongest promise: this is what users depend on most and can least easily migrate. Breaking changes need a major version and a migration note in the changelog. The <a href="./api/">API reference</a> is the authoritative inventory — a test fails if a registered builtin is undocumented, so the promised surface is always enumerable. <code>nitr.ext.*</code> is reserved for user modules and will never be occupied by a builtin.</td></tr><tr><td><strong><code>nitr.toml</code></strong></td><td>Unknown keys are rejected at startup, so a removed key is a loud error, never silence. A renamed key ships with the old name still accepted (and warned about) for one minor cycle before removal.</td></tr><tr><td><strong>The <code>nitr</code> crate (facade)</strong></td><td>Standard semver. This is the supported Rust entry point for applications and embedders.</td></tr><tr><td><strong><code>nitr-core</code> / <code>nitr-std</code> / <code>nitr-http</code></strong></td><td>Published and usable directly, but <strong>explicitly unstable pre-1.0</strong>: they move as fast as the phases need. Depend on the <code>nitr</code> facade unless you are writing an extension crate. The <a href="./library/extension-modules">extension contract</a> (<code>ServerBuilder::module</code>, <code>nitr_table</code>, <code>mount</code>, <code>ModuleFn</code>) is the part expected to settle first.</td></tr><tr><td><strong>CLI flags and output</strong></td><td>Flags follow the <code>nitr.toml</code> policy — deprecate for one minor cycle, then remove. Human-readable <em>output text</em> is not an API; <code>[log] format = &quot;json&quot;</code> and process exit codes are.</td></tr><tr><td><strong><code>nitr-types.lua</code></strong></td><td>Regenerated from the API description each release; versions with the crate and carries no independent promise.</td></tr></tbody></table><h2 id="deprecation-policy" tabindex="-1">Deprecation policy <a class="header-anchor" href="#deprecation-policy" aria-label="Permalink to “Deprecation policy”">​</a></h2><p>Deprecations warn for <strong>one minor version</strong> before removal, and the warning names the replacement (<code>use nitr.time.format instead of ...</code>). Removals and renames are recorded in <code>CHANGELOG.md</code> starting with the first release.</p><h2 id="minimum-supported-rust-version" tabindex="-1">Minimum supported Rust version <a class="header-anchor" href="#minimum-supported-rust-version" aria-label="Permalink to “Minimum supported Rust version”">​</a></h2><p>The MSRV is declared as <code>rust-version</code> in the workspace manifest and checked by a pinned CI matrix entry. <strong>Bumping the MSRV is a minor change, not a breaking one</strong>, and is called out in the changelog.</p><p>The current MSRV is <strong>1.88.0</strong>.</p><h2 id="publishing-order" tabindex="-1">Publishing order <a class="header-anchor" href="#publishing-order" aria-label="Permalink to “Publishing order”">​</a></h2><p>The five crates version together and publish in dependency order:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nitr-core → nitr-std → nitr-http → nitr → nitr-cli</span></span></code></pre></div><h2 id="what-is-deliberately-not-promised" tabindex="-1">What is deliberately not promised <a class="header-anchor" href="#what-is-deliberately-not-promised" aria-label="Permalink to “What is deliberately not promised”">​</a></h2><ul><li>The internal module layout of any crate — <code>pub(crate)</code> boundaries move freely.</li><li>The <code>#[doc(hidden)]</code> fuzzing seams (<code>nitr_std::fuzzing</code>).</li><li>Benchmark names and numbers, the test framework&#39;s failure text, and the dev-mode <code>500</code> page&#39;s markup.</li><li>Behavior reachable only through <code>Server::builder().setup()</code> — the documented low-level escape hatch is sharp by design.</li></ul><h2 id="how-to-depend-on-nitr-safely-today" tabindex="-1">How to depend on Nitr safely today <a class="header-anchor" href="#how-to-depend-on-nitr-safely-today" aria-label="Permalink to “How to depend on Nitr safely today”">​</a></h2><ul><li><strong>Pin a revision.</strong> <code>cargo install --git … --rev &lt;sha&gt;</code> and <code>nitr = { git = &quot;…&quot;, rev = &quot;…&quot; }</code> while there is no crates.io release.</li><li><strong>Run <code>nitr check</code> in CI.</strong> Unknown or removed configuration keys fail loudly there rather than on a deploy.</li><li><strong>Run <code>nitr test</code> in CI.</strong> Requests dispatch through the real router, so a behavioural change in routing or middleware shows up as a test failure.</li><li><strong>Branch on <code>err.kind</code>, never on message text.</strong> <a href="./server/errors#the-error-value">Error kinds</a> are a closed set; messages are not an API.</li></ul>',17)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
